#!/bin/bash
cat <<'EOFB64' | base64 -d > /tmp/grab-new.js

EOFB64
docker cp /tmp/grab-new.js bpos-automation:/app/platforms/grab.js
echo "Copied. Testing..."
docker exec bpos-automation node -e 'require("./platforms/grab.js"); console.log("OK");'
docker restart bpos-automation
sleep 3
docker ps | grep bpos-auto
echo "DONE"
